mapper.select:
SELECT id, name, price, stock, status
FROM product
WHERE id = #{id}

mapper.update:
UPDATE product
SET name = #{request.name}, price = #{request.price}
WHERE id = #{id}

UPDATE product
SET stock = stock - #{quantity}
WHERE id = #{id} AND status = 'ON_SALE' AND stock >= #{quantity}

UPDATE product
SET status = #{status}
WHERE id = #{id}

UPDATE product
SET stock = stock + #{quantity}
WHERE id = #{id}
